#include <algorithm>
#include <climits>
#include <string>
#include <vector>

long long stairWays(int n, const std::vector<int>& steps)
{
    const long long MOD = 1000000007;
    std::vector<long long> ways(n + 1, 0);
    ways[0] = 1;
    for (int i = 1; i <= n; ++i)
        for (int s : steps)
            if (s <= i) ways[i] = (ways[i] + ways[i - s]) % MOD;
    return ways[n];
}

std::vector<int> fewestCoins(const std::vector<int>& coins, int amount)
{
    std::vector<int> best(amount + 1, INT_MAX), last(amount + 1, -1);
    best[0] = 0;
    for (int a = 1; a <= amount; ++a)
        for (int c : coins)
            if (c <= a && best[a - c] != INT_MAX && best[a - c] + 1 < best[a])
            {
                best[a] = best[a - c] + 1;
                last[a] = c;
            }
    if (best[amount] == INT_MAX) return { -1 };
    std::vector<int> used;
    for (int a = amount; a > 0; a -= last[a]) used.push_back(last[a]);
    std::sort(used.begin(), used.end());
    return used;
}

long long changeWays(const std::vector<int>& coins, int amount)
{
    std::vector<long long> ways(amount + 1, 0);
    ways[0] = 1;
    for (int c : coins)
        for (int a = c; a <= amount; ++a) ways[a] += ways[a - c];
    return ways[amount];
}

long long gridPaths(const std::vector<std::string>& grid)
{
    if (grid.empty() || grid[0].empty()) return 0;
    std::size_t rows = grid.size(), cols = grid[0].size();
    std::vector<long long> row(cols, 0);                    // one row is enough
    for (std::size_t r = 0; r < rows; ++r)
        for (std::size_t c = 0; c < cols; ++c)
        {
            if (grid[r][c] == '#') { row[c] = 0; continue; }
            if (r == 0 && c == 0) { row[c] = 1; continue; }
            if (c > 0) row[c] += row[c - 1];                // row[c] still holds the value from above
        }
    return row[cols - 1];
}

long long bestRobbery(const std::vector<int>& houses)
{
    long long take = 0, skip = 0;                           // best totals ending with the last house taken / not taken
    for (int h : houses)
    {
        long long newTake = skip + h;
        skip = std::max(skip, take);
        take = newTake;
    }
    return std::max(take, skip);
}

