#include <numeric>

TEST("climbing stairs") {
    CHECK_EQ(stairWays(4, { 1, 2 }), 5LL);
    CHECK_EQ(stairWays(0, { 1, 2 }), 1LL);
    CHECK_EQ(stairWays(7, { 2, 3 }), 3LL);
    CHECK_EQ(stairWays(5, { 4 }), 0LL);
    CHECK_EQ(stairWays(100000, { 1, 2 }), 967618232LL);
}
TEST("fewest coins") {
    CHECK_EQ(fewestCoins({ 1, 3, 4 }, 6), (std::vector<int>{ 3, 3 }));
    CHECK_EQ(fewestCoins({ 1, 5, 10, 25 }, 63), (std::vector<int>{ 1, 1, 1, 10, 25, 25 }));
    CHECK_EQ(fewestCoins({ 2 }, 3), (std::vector<int>{ -1 }));
    CHECK(fewestCoins({ 7 }, 0).empty());
    auto big = fewestCoins({ 7, 19, 23 }, 9999);
    CHECK_EQ(std::accumulate(big.begin(), big.end(), 0), 9999);
    CHECK_EQ(big.size(), std::size_t{ 437 });
}
TEST("ways to make change") {
    CHECK_EQ(changeWays({ 1, 3, 4 }, 10), 8LL);
    CHECK_EQ(changeWays({ 1, 2, 5 }, 5), 4LL);
    CHECK_EQ(changeWays({ 2 }, 3), 0LL);
    CHECK_EQ(changeWays({ 5 }, 0), 1LL);
    CHECK_EQ(changeWays({ 1, 5, 10, 25, 50, 100 }, 10000), 139946140451LL);
}
TEST("grid paths") {
    CHECK_EQ(gridPaths({ "....", ".#..", "...#", "#..." }), 3LL);
    CHECK_EQ(gridPaths({ "...", "...", "..." }), 6LL);
    CHECK_EQ(gridPaths({ "#.." }), 0LL);
    CHECK_EQ(gridPaths({ ".", "." }), 1LL);
    std::vector<std::string> open(17, std::string(18, '.'));
    CHECK_EQ(gridPaths(open), 1166803110LL);                 // C(33, 16)
}
TEST("house robber") {
    CHECK_EQ(bestRobbery({ 2, 7, 9, 3, 1 }), 12LL);
    CHECK_EQ(bestRobbery({ 5 }), 5LL);
    CHECK_EQ(bestRobbery({}), 0LL);
    CHECK_EQ(bestRobbery({ 2, 1, 1, 2 }), 4LL);
    std::vector<int> big(100000, 1000000);
    CHECK_EQ(bestRobbery(big), 50000LL * 1000000);
}

